"""JSON payload boundary and recursion depth validator."""

from typing import Any, Dict, List
from request_context import ValidationContext
from schema_rule import FieldRule


FORBIDDEN_PREFIXES = ("__", "constructor", "prototype")


class PayloadValidator:
    def __init__(self, max_depth: int = 3, max_keys: int = 10):
        self.max_depth = max_depth
        self.max_keys = max_keys
        self.rules: dict[str, FieldRule] = {}

    def register_rule(self, rule: FieldRule) -> None:
        self.rules[rule.name] = rule

    def validate(self, payload: Any, ctx: ValidationContext, current_depth: int = 1) -> None:
        if not isinstance(payload, dict):
            ctx.add_violation("Payload must be a dictionary")
            return

        if current_depth > self.max_depth:
            ctx.add_violation(f"Payload depth exceeds limit of {self.max_depth}")
            return

        if len(payload) > self.max_keys:
            ctx.add_violation(f"Payload key count exceeds limit of {self.max_keys}")
            return

        for key, val in payload.items():
            if any(key == fp or key.startswith("__") for fp in FORBIDDEN_PREFIXES):
                ctx.add_violation(f"Forbidden special attribute in payload: {key}")

            if isinstance(val, dict):
                self.validate(val, ctx, current_depth + 1)
            elif isinstance(val, list):
                for item in val:
                    if isinstance(item, dict):
                        self.validate(item, ctx, current_depth + 1)
